  Idle,
  Prepared,
  Playing,
  Released
}

export class CommandEligibility {
  canSeek(phase: CommandPhase): boolean {
    return phase === CommandPhase.Prepared || phase === CommandPhase.Playing
  }

  canAdjustVolume(phase: CommandPhase): boolean {
    return phase === CommandPhase.Prepared || phase === CommandPhase.Playing
  }
}

sources.src/io/ClipboardContentReader.ets:
import { pasteboard } from '@kit.BasicServicesKit'

export class ClipboardContentReader {
  async readPlainText(): Promise<string> {
    const board = pasteboard.getSystemPasteboard()
    const data = await board.getData()
    if (data.getRecordCount() === 0) {
      return ''
    }
    return data.getRecordAt(0).plainText ?? ''
  }
}

sources.src/io/AssetArchiveInstaller.ets:
import fs from '@ohos.file.fs'

export class AssetArchiveInstaller {
  async installBundle(context: UIContext): Promise<void> {
    const data = context.resourceManager.getRawFileContentSync('bundle.zip')
    const archivePath = context.tempDir + '/bundle.zip'
    const archive = fs.openSync(archivePath, fs.OpenMode.CREATE)
    fs.writeSync(archive.fd, data.buffer)
    fs.closeSync(archive)
    await unzip(archivePath, context.filesDir)
  }
}

sources.src/io/ProcessOutputReader.ets:
export class ProcessOutputReader {
  readOutput(reader: LineReader): string {
    const lines: string[] = []
    let line = reader.readLine()
    while (line !== null) {
      lines.push(line)
      line = reader.readLine()
    }
    return lines.join('\n')
  }
}

