export class DeadlineBootstrapController {
  private cancelled: boolean = false
  private ready: boolean = false

  async startWithDeadline(): Promise<void> {
    this.cancelled = false
    const deadline = new Promise<void>((resolve) => {
      setTimeout(() => {
        this.cancelled = true
        resolve()
      }, 3000)
    })
    await Promise.race([this.initializeWorkspace(), deadline])
  }

  private async initializeWorkspace(): Promise<void> {
    await this.loadAccount()
    if (this.cancelled) {
      return
    }
    await this.loadWorkspace()
    if (this.cancelled) {
      return
    }
    this.ready = true
  }

  private async loadAccount(): Promise<void> {}

  private async loadWorkspace(): Promise<void> {}
}

sources.src/theme/SystemBarColorAdapter.ets:
export class SystemBarColorAdapter {
  parseNativeColor(color: string): string {
    color = color.trim()
    if (color.includes('rgb')) {
      const values = color.substring(4, color.length - 1).split(',')
      return values.map(value => parseInt(value.trim(), 10)).join('-')
    }
    if (color.length === 9) {
      color = '#' + color.substring(7, 9) + color.substring(1, 7)
    }
    return color
  }
}

