export class PreviewSessionCoordinator {
  private generation: number = 0
  private controller?: PreviewController

  async startPreview(assetId: string): Promise<void> {
    const generation = ++this.generation
    const controller = await PreviewController.create(assetId)
    if (generation != this.generation) {
      controller.dispose()
      return
    }
    this.controller = controller
  }

  replacePreview(assetId: string): void {
    this.stopPreview()
    void this.startPreview(assetId)
  }

  stopPreview(): void {
    this.generation++
    this.controller?.dispose()
    this.controller = undefined
  }
}

export class CheckpointTransaction {
  private staged?: CheckpointRecord

  stageCheckpoint(record: CheckpointRecord): void {
    this.validateCheckpoint(record)
    this.staged = record
  }

  async commitCheckpoint(): Promise<void> {
    const current = this.staged
    if (current == undefined) {
      return
    }
    try {
      await CheckpointStore.write(current)
      this.staged = undefined
    } catch (error) {
      this.rollbackCheckpoint()
      throw error
    }
  }

  rollbackCheckpoint(): void {
    this.staged = undefined
  }

  private validateCheckpoint(record: CheckpointRecord): void {
    if (record.revision <= 0) {
      throw new Error('invalid checkpoint revision')
    }
  }
}

