import { DeferredSignalBuffer } from '../ingress/DeferredSignalBuffer'

export class SignalActivationPolicy {
  activateAfterSurfaceAttach(buffer: DeferredSignalBuffer): void {
    const pendingSignal = buffer.consumeWhenAttached()
    if (pendingSignal.length > 0) {
      NotificationRuntime.activate(pendingSignal)
    }
  }
}

export interface ScheduledWork {
  deadline: number
  insertionSequence: number
}

export class StableSchedule {
  orderReadyWork(ready: ScheduledWork[]): ScheduledWork[] {
    return ready.sort((left, right) => {
      if (left.deadline !== right.deadline) {
        return left.deadline - right.deadline
      }
      return left.insertionSequence - right.insertionSequence
    })
  }
}

export class DeferredSignalBuffer {
  private pendingSignal: string = ''

  preserveBeforeReady(signal: string): void {
    this.pendingSignal = signal
  }

  consumeWhenAttached(): string {
    const signal = this.pendingSignal
    this.pendingSignal = ''
    return signal
  }
}

export interface DeferredSignalRecord {
  pendingSignal: string
  bufferedBeforeReady: boolean
  activatedAfterAttach: boolean
}

export interface DeadlineReplayRecord {
  earliestDeadline: number
  insertionSequence: number
  readyWorkCount: number
}

